#include <stdio.h>

unsigned long long factorial(int n) { return n <= 1 ? 1 : (unsigned long long)n * factorial(n - 1); }

int main(void) {
    int n;
    scanf("%d", &n);
    printf("%llu\n", factorial(n));
    return 0;
}
